1	import { and, eq } from "drizzle-orm";
2	import { Hono } from "hono";
3	import { rootLogger } from "../shared/logger";
4	import type { Db } from "./db/client";
5	import { posts, revisions, sites } from "./db/schema";
6	import { triggerDeployHook } from "./deploy-hook";
7	
8	const logger = rootLogger.child("api");
9	
10	interface SavePostBody {
11	  readonly title?: unknown;
12	  readonly body?: unknown;
13	}
14	
15	function isSavePostBody(value: unknown): value is { title: string; body: string } {
16	  if (typeof value !== "object" || value === null) return false;
17	  const candidate = value as SavePostBody;
18	  return typeof candidate.title === "string" && typeof candidate.body === "string";
19	}
20	
21	/**
22	 * Builds the API against a given database rather than reaching for a module-
23	 * level singleton, so a test can pass an in-memory one and never touch the
24	 * file the running server uses. server/index.ts is the only caller that
25	 * passes a real, file-backed `Db`.
26	 */
27	export function createApp(db: Db) {
28	  const app = new Hono();
29	
30	  app.get("/health", (c) => c.json({ status: "ok" }));
31	
32	  app.get("/sites", async (c) => {
33	    const rows = await db.select().from(sites);
34	    return c.json(rows);
35	  });
36	
37	  app.get("/sites/:siteSlug/posts", async (c) => {
38	    const site = await findSiteBySlug(db, c.req.param("siteSlug"));
39	    if (!site) return c.json({ error: "Site not found." }, 404);
40	
41	    const rows = await db.select().from(posts).where(eq(posts.siteId, site.id));
42	    return c.json(rows);
43	  });
44	
45	  app.get("/sites/:siteSlug/posts/:postId", async (c) => {
46	    const site = await findSiteBySlug(db, c.req.param("siteSlug"));
47	    if (!site) return c.json({ error: "Site not found." }, 404);
48	
49	    const post = await findSitePost(db, site.id, c.req.param("postId"));
50	    if (!post) return c.json({ error: "Post not found." }, 404);
51	
52	    return c.json(post);
53	  });
54	
55	  app.put("/sites/:siteSlug/posts/:postId", async (c) => {
56	    const site = await findSiteBySlug(db, c.req.param("siteSlug"));
57	    if (!site) return c.json({ error: "Site not found." }, 404);
58	
59	    const post = await findSitePost(db, site.id, c.req.param("postId"));
60	    if (!post) return c.json({ error: "Post not found." }, 404);
61	
62	    const body = await c.req.json().catch(() => null);
63	    if (!isSavePostBody(body)) {
64	      return c.json({ error: "A draft save needs a title and a body, both strings." }, 400);
65	    }
66	
67	    const [updated] = await db
68	      .update(posts)
69	      .set({ title: body.title, body: body.body, updatedAt: new Date().toISOString() })
70	      .where(eq(posts.id, post.id))
71	      .returning();
72	
73	    return c.json(updated);
74	  });
75	
76	  // Publishing writes a revision snapshot, flips the post to "published",
77	  // and calls the site's deploy hook — see docs/deploy-hooks.md for what
78	  // happens when that last step fails.
79	  app.post("/sites/:siteSlug/posts/:postId/publish", async (c) => {
80	    const site = await findSiteBySlug(db, c.req.param("siteSlug"));
81	    if (!site) return c.json({ error: "Site not found." }, 404);
82	
83	    const post = await findSitePost(db, site.id, c.req.param("postId"));
84	    if (!post) return c.json({ error: "Post not found." }, 404);
85	
86	    // One write, not two: a revision row for a post that never flipped to
87	    // published is a snapshot of something the site never served. The
88	    // callback is synchronous because this driver is — an async one would let
89	    // the transaction commit before the work inside it had finished.
90	    const updated = db.transaction((tx) => {
91	      tx.insert(revisions).values({ postId: post.id, title: post.title, body: post.body }).run();
92	      const [row] = tx
93	        .update(posts)
94	        .set({ status: "published", updatedAt: new Date().toISOString() })
95	        .where(eq(posts.id, post.id))
96	        .returning()
97	        .all();
98	      return row;
99	    });
100	
101	    logger.info({ siteSlug: site.slug, postId: post.id }, "Started publishing a post.");
102	    const deployResult = await triggerDeployHook(site.slug, site.deployHookUrl);
103	    logger.info(
104	      { siteSlug: site.slug, postId: post.id, deployTriggered: deployResult.ok },
105	      "Completed publishing a post.",
106	    );
107	
108	    return c.json({ post: updated, deployTriggered: deployResult.ok });
109	  });
110	
111	  return app;
112	}
113	
114	async function findSiteBySlug(db: Db, slug: string) {
115	  const [site] = await db.select().from(sites).where(eq(sites.slug, slug));
116	  return site;
117	}
118	
119	async function findSitePost(db: Db, siteId: number, postIdParam: string) {
120	  const postId = Number(postIdParam);
